     5	public class ClaimOffice {
     6	
     7	    private static final int PROCESSING_FEE_IN_G = 5;
     8	
     9	    private final PolicyWideModifiers policyWideModifiers;
    10	
    11	    public ClaimOffice(Customer customer) {
    12	        this.policyWideModifiers = new PolicyWideModifiers(customer);
    13	    }
    14	
    15	    /**
    16	     * The policy base premium is the sum of the base premiums of the main items
    17	     * and of the components, each priced by its own MHPCO pricing policy.
    18	     *
    19	     * The MHPCO names this amount in its own rules, so it is observable inside
    20	     * the domain; it is not part of what the office offers a caller, which is
    21	     * a quote.
    22	     */
    23	    int basePremium(List<Item> items) {
    24	        return MainItemPricing.mainItemsBasePremium(items)
    25	                + ComponentPricing.componentsBasePremium(items);
    26	    }
    27	
    28	    /**
    29	     * Item-specific modifiers apply to the base premium of the affected item,
    30	     * not to the policy total.
    31	     */
    32	    BigDecimal premiumAfterItemModifiers(List<Item> items) {
    33	        return BigDecimal.valueOf(basePremium(items))
    34	                .add(ItemRiskSurcharges.totalItemSurcharges(items));
    35	    }
    36	
    37	    /**
    38	     * The MHPCO assembles a premium from a base premium and two families of
    39	     * modifier. Neither family is measured against the other's amounts: the
    40	     * item-specific risk surcharges are measured against the base premium of
    41	     * each affected item, the policy-wide modifiers against the policy base
    42	     * premium as a whole. Both are therefore added to the policy base premium
    43	     * side by side rather than in sequence, and the processing fee is added at
    44	     * the very end.
    45	     */
    46	    public int quote(List<Item> items) {
    47	        InsurableItems.requireAllInsurable(items);
    48	        BigDecimal policyBasePremium = BigDecimal.valueOf(basePremium(items));
    49	        BigDecimal quotedPremium = premiumAfterItemModifiers(items)
    50	                .add(policyWideModifiers.totalPolicyModifiers(policyBasePremium))
    51	                .add(BigDecimal.valueOf(PROCESSING_FEE_IN_G));
    52	        policyWideModifiers.recordContractIssued();
    53	        return roundedUpInTheMhpcoFavour(quotedPremium);
    54	    }
    55	
    56	    /**
    57	     * All amounts are rounded to whole G in the MHPCO's favour: a premium the
    58	     * customer owes is rounded up.
    59	     */
    60	    private static int roundedUpInTheMhpcoFavour(BigDecimal premium) {
    61	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    62	    }
    63	}
